components.css:
.ds-enter { display: inline-flex; align-items: center; justify-content: center; gap: 8px; cursor: pointer; border: 1px solid var(--orange, #ff7a18); border-radius: 0; background: var(--orange, #ff7a18); color: #211024; padding: 8px 12px; font: 600 1rem/1.5rem "Avenir Next", system-ui, sans-serif; transition: background-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)), transform 280ms var(--ease, cubic-bezier(.22, 1, .36, 1)), border-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)); }
.ds-enter:hover { background: #ffa35d; border-color: #ffa35d; }
.ds-enter:focus-visible { outline: 2px solid var(--cyan, #00f0ff); outline-offset: 3px; }
.ds-enter:active { transform: translateY(1px); }
.ds-enter-key { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; border: 1px solid var(--edge, #4b355c); min-width: 20px; padding: 2px 4px; font: inherit; color: inherit; font-variant-numeric: tabular-nums; }
.ds-enter-key { border-color: #66371e; }
@media (prefers-reduced-motion: reduce) { .ds-enter { transition: none; } }

.ds-sound { display: inline-flex; align-items: center; justify-content: center; gap: 8px; cursor: pointer; border: 1px solid var(--edge, #4b355c); border-radius: 0; background: var(--panel, #171024); color: var(--light, #fff4e6); padding: 8px 12px; font: 600 .875rem/1.25rem "Avenir Next", system-ui, sans-serif; transition: background-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)), transform 280ms var(--ease, cubic-bezier(.22, 1, .36, 1)), border-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)); }
.ds-sound:hover { background: var(--raised, #241631); border-color: var(--muted, #bba9cb); }
.ds-sound:focus-visible { outline: 2px solid var(--cyan, #00f0ff); outline-offset: 3px; }
.ds-sound:active { transform: translateY(1px); }
.ds-sound-key { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; border: 1px solid var(--edge, #4b355c); min-width: 20px; padding: 2px 4px; font: inherit; color: inherit; font-variant-numeric: tabular-nums; }
.ds-sound-key { color: var(--muted, #bba9cb); font-size: .75rem; }
@media (prefers-reduced-motion: reduce) { .ds-sound { transition: none; } }

.ds-legend-preview { display: inline-flex; align-items: center; gap: 8px; padding: 4px; background: var(--ground, #10091d); color: var(--muted, #bba9cb); font: 600 .75rem/1rem "Avenir Next", system-ui, sans-serif; }
.ds-legend-key { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; border: 1px solid var(--edge, #4b355c); min-width: 20px; padding: 2px 4px; font: inherit; color: inherit; font-variant-numeric: tabular-nums; }
.ds-legend-key { color: var(--light, #fff4e6); }

.ds-hp { box-sizing: border-box; background: #100920ed; border: 1px solid #4b355cb8; padding: 8px; min-width: 0; color: var(--light, #fff4e6); font: 600 .75rem/1rem "Avenir Next", system-ui, sans-serif; font-variant-numeric: tabular-nums; width: clamp(90px, 18cqw, 168px); }
    .ds-hp-label { color: var(--muted, #bba9cb); }
    .ds-hp strong { font-weight: 600; }
    @media (max-width: 640px) { .ds-hp { padding: 2px 4px; } }

    .ds-hp-meter { height: 4px; background: #352543; margin-top: 4px; overflow: hidden; }
    .ds-hp-fill { display: block; width: 100%; height: 100%; background: var(--orange, #ff7a18); transform-origin: left; transform: scaleX(var(--ds-meter, 1)); }
.ds-hp-row { display: flex; justify-content: space-between; gap: 8px; }

.ds-xp { box-sizing: border-box; background: #100920ed; border: 1px solid #4b355cb8; padding: 8px; min-width: 0; color: var(--light, #fff4e6); font: 600 .75rem/1rem "Avenir Next", system-ui, sans-serif; font-variant-numeric: tabular-nums;  }
    .ds-xp-label { color: var(--muted, #bba9cb); }
    .ds-xp strong { font-weight: 600; }
    @media (max-width: 640px) { .ds-xp { padding: 2px 4px; } }

    .ds-xp-meter { height: 4px; background: #352543; margin-top: 4px; overflow: hidden; }
    .ds-xp-fill { display: block; width: 100%; height: 100%; background: var(--gold, #ffcf83); transform-origin: left; transform: scaleX(var(--ds-meter, 1)); }
.ds-xp-row { display: flex; justify-content: space-between; gap: 8px; }

.ds-dash { box-sizing: border-box; background: #100920ed; border: 1px solid #4b355cb8; padding: 8px; min-width: 0; color: var(--light, #fff4e6); font: 600 .75rem/1rem "Avenir Next", system-ui, sans-serif; font-variant-numeric: tabular-nums; width: fit-content; min-width: 92px; }
.ds-dash-label { color: var(--muted, #bba9cb); }
.ds-dash strong { font-weight: 600; }
@media (max-width: 640px) { .ds-dash { padding: 2px 4px; } }

.ds-dash-meter { height: 4px; background: #352543; margin-top: 4px; overflow: hidden; }
.ds-dash-fill { display: block; width: 100%; height: 100%; background: var(--cyan, #00f0ff); transform-origin: left; transform: scaleX(var(--ds-meter, 1)); }

.ds-dash-row { display: flex; align-items: center; gap: 4px; white-space: nowrap; }
.ds-dash-icon { width: 16px; height: 16px; }
@media (max-width: 640px) { .ds-dash { min-width: 68px; } .ds-dash-icon { width: 12px; height: 12px; } }

.ds-gear { box-sizing: border-box; background: #100920ed; border: 1px solid #4b355cb8; padding: 8px; min-width: 0; color: var(--light, #fff4e6); font: 600 .75rem/1rem "Avenir Next", system-ui, sans-serif; font-variant-numeric: tabular-nums; display: flex; align-items: center; gap: 4px; width: fit-content; }
.ds-gear-label { color: var(--muted, #bba9cb); }
.ds-gear strong { font-weight: 600; }
@media (max-width: 640px) { .ds-gear { padding: 2px 4px; } }

.ds-gear-icon { width: 24px; height: 24px; flex: none; }
.ds-gear strong { color: var(--costume, var(--orange, #ff7a18)); }

.ds-upgrade-card { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; min-width: 0; padding: 12px; text-align: left; overflow-wrap: anywhere; cursor: pointer; border: 1px solid #826234; border-radius: 0; background: #22132d; color: var(--light, #fff4e6); font: 400 1rem/normal "Avenir Next", system-ui, sans-serif; transition: background-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)), transform 280ms var(--ease, cubic-bezier(.22, 1, .36, 1)), border-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)); }
.ds-upgrade-top { display: flex; width: 100%; align-items: flex-start; justify-content: space-between; gap: 4px; }
.ds-upgrade-icon { flex: none; width: 40px; height: 40px; }
.ds-upgrade-key { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; border: 1px solid var(--edge, #4b355c); min-width: 20px; padding: 2px 4px; font: inherit; color: inherit; font-variant-numeric: tabular-nums; }
.ds-upgrade-key { color: var(--gold, #ffcf83); }
.ds-upgrade-name { font-size: 1rem; line-height: 1.25rem; font-weight: 600; }
.ds-upgrade-effect { font-size: .875rem; line-height: 1.25rem; }
.ds-upgrade-stacks { color: var(--muted, #bba9cb); margin-top: auto; font-size: .75rem; line-height: 1rem; font-weight: 600; }
.ds-upgrade-card:hover:not(:disabled), .ds-upgrade-card:focus-visible { background: #352144; border-color: var(--gold, #ffcf83); }
.ds-upgrade-card:focus-visible { outline: 2px solid var(--cyan, #00f0ff); outline-offset: 3px; }
.ds-upgrade-card:active:not(:disabled) { transform: translateY(1px); }
.ds-upgrade-card:disabled { border-color: var(--edge, #4b355c); opacity: .66; cursor: default; }
@media (max-width: 640px) { .ds-upgrade-card { padding: 8px; } .ds-upgrade-name { font-size: .875rem; } .ds-upgrade-icon { width: 24px; height: 24px; } }
@media (prefers-reduced-motion: reduce) { .ds-upgrade-card { transition: none; } }

.ds-level-screen { box-sizing: border-box; display: grid; place-items: center; min-height: 310px; padding: 24px; text-align: center; color: var(--light, #fff4e6); background: linear-gradient(#0a0018c9, #0a0018c9), linear-gradient(#251434 1px, transparent 1px), linear-gradient(90deg, #251434 1px, #130722 1px); background-size: auto, 32px 32px, 32px 32px; font-family: "Avenir Next", system-ui, sans-serif; }
.ds-level-content { width: min(100%, 640px); }
.ds-level-heading { margin: 0 0 8px; font-size: 3rem; font-weight: 600; line-height: 1; letter-spacing: -.04em; text-wrap: balance; }
.ds-level-note { margin: 0; color: var(--muted, #bba9cb); font-size: .875rem; line-height: 1.25rem; text-wrap: pretty; }
.ds-level-choices { margin: 24px auto 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
@media (max-width: 640px) { .ds-level-screen { padding: 12px; } .ds-level-heading { font-size: 2.25rem; line-height: 2.5rem; } .ds-level-choices { margin-top: 12px; gap: 4px; } }

.ds-level-card { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; min-width: 0; padding: 12px; text-align: left; overflow-wrap: anywhere; cursor: pointer; border: 1px solid #826234; border-radius: 0; background: #22132d; color: var(--light, #fff4e6); font: 400 1rem/normal "Avenir Next", system-ui, sans-serif; transition: background-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)), transform 280ms var(--ease, cubic-bezier(.22, 1, .36, 1)), border-color 240ms var(--ease, cubic-bezier(.22, 1, .36, 1)); }
.ds-level-top { display: flex; width: 100%; align-items: flex-start; justify-content: space-between; gap: 4px; }
.ds-level-icon { flex: none; width: 40px; height: 40px; }
.ds-level-key { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; border: 1px solid var(--edge, #4b355c); min-width: 20px; padding: 2px 4px; font: inherit; color: inherit; font-variant-numeric: tabular-nums; }
.ds-level-key { color: var(--gold, #ffcf83); }
.ds-level-name { font-size: 1rem; line-height: 1.25rem; font-weight: 600; }
.ds-level-effect { font-size: .875rem; line-height: 1.25rem; }
.ds-level-stacks { color: var(--muted, #bba9cb); margin-top: auto; font-size: .75rem; line-height: 1rem; font-weight: 600; }
.ds-level-card:hover:not(:disabled), .ds-level-card:focus-visible { background: #352144; border-color: var(--gold, #ffcf83); }
.ds-level-card:focus-visible { outline: 2px solid var(--cyan, #00f0ff); outline-offset: 3px; }
.ds-level-card:active:not(:disabled) { transform: translateY(1px); }
.ds-level-card:disabled { border-color: var(--edge, #4b355c); opacity: .66; cursor: default; }
@media (max-width: 640px) { .ds-level-card { padding: 8px; } .ds-level-name { font-size: .875rem; } .ds-level-icon { width: 24px; height: 24px; } }
@media (prefers-reduced-motion: reduce) { .ds-level-card { transition: none; } }

.ds-results { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); margin: 0; text-align: center; background: var(--arena, #0a0018); color: var(--light, #fff4e6); border-block: 1px solid var(--edge, #4b355c); font-family: "Avenir Next", system-ui, sans-serif; }
.ds-results-item { padding: 8px 4px; }
.ds-results-item + .ds-results-item { border-left: 1px solid var(--edge, #4b355c); }
.ds-results-label { color: var(--muted, #bba9cb); font-size: .75rem; line-height: 1rem; font-weight: 600; }
.ds-results-value { margin: 0; font-size: 1rem; line-height: 1.5rem; font-weight: 600; font-variant-numeric: tabular-nums; }
